// ---------------------------------------------------------------------------
// Every number in this manuscript is read from results/paper_facts.json, which
// paper_src/make_facts.py builds from the experiment output.  Re-run the
// experiments -> re-run make_facts.py -> rebuild this file, and the text, the
// tables and the abstract are updated together.  A fact that does not exist yet
// (its experiment has not been run) is printed as a yellow placeholder.
// ---------------------------------------------------------------------------
const FACTS = fs.existsSync(RES + "paper_facts.json")
  ? JSON.parse(fs.readFileSync(RES + "paper_facts.json", "utf8")) : {};
const missing = new Set();
function fact(key) {
  if (FACTS[key] === undefined || FACTS[key] === null) { missing.add(key); return null; }
  return FACTS[key];
}
const F = "Times New Roman";
const t = (text, o = {}) => new TextRun({ text, font: F, size: 20, ...o });
const TBD = (s) => new TextRun({ text: s, font: F, size: 20, bold: true, color: "C00000", highlight: "yellow" });
const p = (x, opts = {}) => new Paragraph({ style: S.text,
  children: Array.isArray(x) ? x : [t(x)], ...opts });
const pNoIndent = (x, opts = {}) => new Paragraph({ style: S.textNoIndent,
  children: Array.isArray(x) ? x : [t(x)], ...opts });
const h1 = (s) => new Paragraph({ style: S.h1, children: [new TextRun({ text: s, font: F, size: 20, bold: true })] });
const h2 = (s) => new Paragraph({ style: S.h2, children: [new TextRun({ text: s, font: F, size: 20, bold: true, italics: true })] });
// MDPI: table captions above the table, figure captions below the figure
const cap = (s) => new Paragraph({ style: s.startsWith("Table") ? S.tableCaption : S.figureCaption,
  children: [t(s, { size: 18 })] });
const bullet = (s) => new Paragraph({ numbering: { reference: "bul", level: 0 }, spacing: { after: 60 },
  alignment: AlignmentType.JUSTIFIED, indent: { left: 400, hanging: 200 },
  children: Array.isArray(s) ? s : [t(s)] });
function table(headers, rows, widths, fs = 17) {
  const total = widths.reduce((a, b) => a + b, 0);
  const cell = (txt, w, bold, shade) => new TableCell({ width: { size: w, type: WidthType.DXA },
    shading: shade ? { type: ShadingType.CLEAR, fill: "E7E6E6", color: "auto" } : undefined,
    margins: { top: 40, bottom: 40, left: 60, right: 60 },
    children: [new Paragraph({ alignment: AlignmentType.CENTER, children: [typeof txt === "string" ? new TextRun({ text: txt, font: F, size: fs, bold }) : txt] })] });
  const mk = (cells, bold, shade) => new TableRow({ tableHeader: !!bold,
    children: cells.map((c, i) => cell(c, widths[i], bold, shade)) });
  return new Table({ width: { size: total, type: WidthType.DXA }, columnWidths: widths,
    borders: { top: { style: BorderStyle.SINGLE, size: 6 }, bottom: { style: BorderStyle.SINGLE, size: 6 }, left: { style: BorderStyle.NONE }, right: { style: BorderStyle.NONE }, insideHorizontal: { style: BorderStyle.SINGLE, size: 2, color: "999999" }, insideVertical: { style: BorderStyle.NONE } },
    rows: [mk(headers, true, true), ...rows.map(r => mk(r, false, false))] });
}
const img = (file, w, h) => new Paragraph({ style: S.figure, alignment: AlignmentType.CENTER,
  children: [new ImageRun({ type: "png", data: fs.readFileSync(RES + file), transformation: { width: w, height: h } })] });


// tagged template: P`text ${"fact_key"} more text`  ->  array of TextRuns
function P(strings, ...keys) {
  const out = [];
  strings.forEach((s, i) => {
    if (s) out.push(t(s));
    if (i < keys.length) {
      const k = keys[i], v = fact(k);
      out.push(v === null ? TBD(`[${k}]`) : t(String(v)));
    }
  });
  return out;
}
// table whose body comes from a fact key; falls back to a single yellow row
function factTable(headers, key, widths, fs = 17, note = null) {
  const rows = fact(key);
  if (!rows) return table(headers, [[TBD(`[${key}: run the experiment, then paper_src/make_facts.py]`)]
    .concat(Array(headers.length - 1).fill(""))], widths, fs);
  return table(headers, rows, widths, fs);
}
function datasetTable() {
  const extra = fact("tab_native_extra");          // [name, rows, features, model, ...]
  const look = (name) => {
    if (!extra) return [TBD("TBD"), TBD("TBD")];
    const r = extra.find(x => String(x[0]).toLowerCase().replace(/[^a-z0-9]/g, "")
                              === name.toLowerCase().replace(/[^a-z0-9]/g, ""));
    return r ? [r[1], r[2]] : [TBD("TBD"), TBD("TBD")];
  };
  const rows = [["TON_IoT (network) [12–14]", "IoT district traffic", fact("ton_rows") || TBD("TBD"),
                 "normal + 9 attacks", fact("ton_features") || TBD("TBD")],
                ["CIC-IDS2017 [16]", "Enterprise / data centre", look("CIC-IDS2017")[0], "benign + 14 attacks", look("CIC-IDS2017")[1]],
                ["UNSW-NB15 [17]", "Enterprise (2nd)", look("UNSW-NB15")[0], "normal + 9 categories", look("UNSW-NB15")[1]]];
  return table(["Dataset", "Layer represented", "Rows used", "Classes", "Native features (bias-aware)"],
               rows, [2100, 2100, 1400, 1900, 1526]);
}
const IMG = (file, w, h) => fs.existsSync(RES + file)
  ? img(file, w, h)
  : p([TBD(`[figure ${file} not found - run the experiment that produces it]`)]);

